// Use a static fuzz buffer so its lifetime safely exceeds the decoder's lifetime.
// FUZZ_PARAM(uint8_t[1024]) provides a non-null pointer to a 1024-byte buffer of random data.
const uint8_t *encoded_buf = *FUZZ_PARAM(uint8_t[1024]);
// Choose a size in range [0, 1024]. If size > 0, buffer is guaranteed non-null.
size_t encoded_size = (size_t)(*FUZZ_PARAM(unsigned int) % 1025);
// Construct the decoder with a valid buffer/size pairing.
// - When encoded_size == 0, passing a non-null buffer is still valid (no reads will occur).
// - When encoded_size > 0, encoded_buf is non-null (by construction above).
Pinetime::Tools::RleDecoder *decoder = new Pinetime::Tools::RleDecoder(encoded_buf, encoded_size);
// Track metadata for downstream stubs (optional but useful for validation/coverage).
FUZZ_SET_ATTR_INT(decoder, "encoded_size", (int)encoded_size);
// decoder is returned as an output object and remains persistent across calls.

// The decoder instance must have been constructed already; the fuzzer runtime enforces this by
// supplying a persistent Pinetime::Tools::RleDecoder * from its object pool.
// Choose a maxBytes limit in [0, 1024] to bound work and stay performant.
size_t max_bytes = (size_t)(*FUZZ_PARAM(unsigned int) % 1025);
// Allocate a writable output buffer only if max_bytes > 0, to satisfy API constraints:
// - If maxBytes > 0, output must be non-null and writable for at least maxBytes bytes.
// - If maxBytes == 0, output may be null and the call is a no-op.
uint8_t *out_ptr = nullptr;
std::vector<uint8_t> out_buf;
if (max_bytes > 0) {
  out_buf.resize(max_bytes, 0);
  out_ptr = out_buf.data();
}
// Invoke the target API. This is stateful but not thread-safe; we call it in a single-threaded context.
decoder->DecodeNext(out_ptr, max_bytes);
// No status is returned; we only ensure invariants were respected by construction above.
// Return the decoder as an output so it remains in the pool for further incremental decoding.
